import { Component, Host, Prop, h } from "@stencil/core";

/**
 * @since 2.6.0
 * @status stable
 *
 * @slot - The label's content.
 *
 * @part base - The component's base wrapper.
 */

@Component({
	tag: "hbr-label",
	styleUrl: "label.scss",
	shadow: true,
})
export class Label {
	/** The label's size. */
	@Prop({ reflect: true }) size: "small" | "medium" | "large" = "medium";

	/** The label's usage. */
	@Prop({ reflect: true }) variant:
		| "nav-group"
		| "nav-menu-group"
		| "menu-group";

	render() {
		return (
			<Host>
				<div
					part="base"
					class={{
						label: true,
						[`label--${this.variant}`]: !!this.variant,
						[`label--${this.size}`]: true,
					}}
				>
					<slot />
				</div>
			</Host>
		);
	}
}
